// Generated by the site build. It runs the real setup script and the real data
// and route layers of the TypeScript project, with the types removed, over sql.js.

importScripts("https://cdn.jsdelivr.net/npm/sql.js@1.13.0/dist/sql-wasm.js");

// Node has a built-in SQLite module called node:sqlite, and a browser does not.
// sql.js is SQLite compiled to run in a browser. This file gives the code from
// server.ts the same small interface that node:sqlite offers, backed by sql.js.

// Each database "file" lives in memory, and opening the same name twice returns
// the same database, so the setup script and the server share one machine.
const openDatabases = new Map();

class StatementSync {
  constructor(database, sqlText) {
    this.database = database;
    this.sqlText = sqlText;
    // Preparing a statement checks the SQL straight away, as node:sqlite does.
    database.prepare(sqlText).free();
  }

  // Return every matching row as an object.
  all(...values) {
    const statement = this.database.prepare(this.sqlText);
    try {
      statement.bind(values);
      const rows = [];
      while (statement.step()) {
        rows.push(statement.getAsObject());
      }
      return rows;
    } finally {
      statement.free();
    }
  }

  // Return the first matching row, or undefined when nothing matched.
  get(...values) {
    return this.all(...values)[0];
  }

  // Run a statement that changes data, and report how many rows it changed.
  run(...values) {
    this.database.run(this.sqlText, values);
    return { changes: this.database.getRowsModified(), lastInsertRowid: 0 };
  }
}

class DatabaseSync {
  constructor(fileName) {
    if (!openDatabases.has(fileName)) {
      openDatabases.set(fileName, new SQL.Database());
    }
    this.database = openDatabases.get(fileName);
  }

  exec(sqlText) {
    this.database.exec(sqlText);
  }

  prepare(sqlText) {
    return new StatementSync(this.database, sqlText);
  }

  // The data must survive a close, because the browser has no file to reopen.
  close() {}
}


const path = { join: (...parts) => parts.join("/") };

// A stand-in for the HTTP layer of server.ts, for use inside a browser.
//
// A browser cannot open a network port, so the real HTTP layer (the code that
// uses node:http) cannot run here. The data layer and the route layer do not
// need a network, so the build copies them out of server.ts unchanged, and
// this file replaces only the top layer.

// The pieces of server.ts that this file needs.
                
                                                                                                         
                                             
                                             
                                          
  

                                               

function createAnswerer(machine         ) {
  // Answer one request and return a status code and the body text.
  return function answer(httpMethod        , urlPath        )         {
    try {
      // The same route table that the real server uses. The first match wins.
      for (const route of machine.ROUTES) {
        const pathMatch = route.pathPattern.exec(urlPath);
        if (route.httpMethod === httpMethod && pathMatch !== null) {
          return { status: 200, body: JSON.stringify(route.handler(...pathMatch.slice(1))) };
        }
      }
      return { status: 404, body: JSON.stringify({ error: "No such route." }) };
    } catch (error) {
      // The same translation from errors to status codes as the real server.
      if (error instanceof machine.BadRequest) {
        return { status: 400, body: JSON.stringify({ error: error.message }) };
      } else if (error instanceof machine.NoSuchSlot) {
        return { status: 404, body: JSON.stringify({ error: error.message }) };
      } else if (error instanceof machine.SoldOut) {
        return { status: 409, body: JSON.stringify({ error: error.message }) };
      }
      return { status: 500, body: JSON.stringify({ error: "Something went wrong on the server." }) };
    }
  };
}


async function start() {
  // Download and start SQLite. The SQL object is what the shim builds databases from.
  globalThis.SQL = await initSqlJs({
    locateFile: (fileName) => "https://cdn.jsdelivr.net/npm/sql.js@1.13.0/dist/" + fileName,
  });

  // setup-db.ts, unchanged apart from its types and its import lines.
  (function runSetupScript() {
    // Create the vending machine database and fill it with a few snacks.
    //
    // Run this file once before you start the server.
    // Running it again resets the machine to its starting state.


    // The database is one ordinary file in the project folder.
    // "/app/src" is the folder that holds this file, which is src,
    // so ".." leads to the project folder above it.
    const DATABASE_FILE = path.join("/app/src", "..", "vending.db");

    // The schema describes the shape of our data: one table with four columns.
    // The comments after the double dashes are SQL comments.
    const SCHEMA = `
    DROP TABLE IF EXISTS inventory;

    CREATE TABLE inventory (
        slot_id     TEXT    PRIMARY KEY,                           -- identifies one slot, for example A1
        item_name   TEXT    NOT NULL,                              -- every slot must have a name
        price_cents INTEGER NOT NULL CHECK (price_cents >= 0),     -- whole cents, never decimals
        stock       INTEGER NOT NULL CHECK (stock >= 0)            -- the database refuses negative stock
    );
    `;

    // Each entry is one row: [slot_id, item_name, price_cents, stock].
    // The type after the colon says "a list of lists, each holding two strings
    // and two numbers". The Oat Biscuits start with no stock so that we can test
    // a sold-out slot.
    const STARTING_STOCK                                     = [
      ["A1", "Sparkling Water", 175, 8],
      ["A2", "Salted Peanuts", 125, 5],
      ["B1", "Chocolate Bar", 200, 3],
      ["B2", "Oat Biscuits", 150, 0],
    ];

    // Opening the database opens the file, and creates it if it does not exist.
    const database = new DatabaseSync(DATABASE_FILE);

    // A transaction groups the work: either all of it happens or none of it does.
    database.exec("BEGIN");
    database.exec(SCHEMA);

    // A prepared statement is SQL that the database reads once and can run many
    // times. The question marks are placeholders, and the values travel to the
    // database separately from the SQL text.
    const insertSlot = database.prepare(
      "INSERT INTO inventory (slot_id, item_name, price_cents, stock) VALUES (?, ?, ?, ?)",
    );
    for (const slotRow of STARTING_STOCK) {
      // The three dots spread the four values of the row into four arguments.
      insertSlot.run(...slotRow);
    }
    database.exec("COMMIT");

    // Read the rows back so that we can see what was stored.
    const storedRows = database
      .prepare("SELECT slot_id, item_name, price_cents, stock FROM inventory ORDER BY slot_id")
      .all();
    for (const storedRow of storedRows) {
      console.log(Object.values(storedRow));
    }

    database.close();

  })();

  // The data layer and route layer from server.ts.
  const machine = (function loadMachine() {
    // The shape of one slot. It matches one row of the inventory table and the
    // JSON that we send to the browser. A type exists only while we write and
    // check the program. Node removes it before the program runs.
             
                  
                    
                      
                
  

    // --- Settings ----------------------------------------------------------------

    // 127.0.0.1 means "this computer", so only programs on your own machine can connect.
    const HOST = "127.0.0.1";

    // The port decides which program on this computer receives the request.
    const PORT = 8000;

    // "/app/src" is the folder that holds this file, which is src,
    // so ".." leads to the project folder above it.
    const PROJECT_FOLDER = path.join("/app/src", "..");
    const DATABASE_FILE = path.join(PROJECT_FOLDER, "vending.db");
    const PUBLIC_FOLDER = path.join(PROJECT_FOLDER, "public");

    // The only files that the server will send. Each URL path maps to a file name
    // and a Content-Type. A fixed list stops visitors from asking for other files,
    // such as server.ts or vending.db, by typing a path like /../src/server.ts.
    const STATIC_FILES = new Map([
      ["/", { fileName: "index.html", contentType: "text/html; charset=utf-8" }],
      ["/style.css", { fileName: "style.css", contentType: "text/css; charset=utf-8" }],
      ["/app.js", { fileName: "app.js", contentType: "text/javascript; charset=utf-8" }],
    ]);

    // A valid slot id is one capital letter followed by one digit, such as A1 or B2.
    const SLOT_ID_PATTERN = /^[A-Z][0-9]$/;

    // --- Errors ------------------------------------------------------------------
    // The data layer reports problems by throwing these errors. Each name
    // describes a problem in the language of the vending machine, and the HTTP
    // layer decides which status code each problem deserves.

    class BadRequest extends Error {}
    class NoSuchSlot extends Error {}
    class SoldOut extends Error {}

    // --- Data layer --------------------------------------------------------------
    // These functions are the only place where the program talks to the database.

    // We open one connection for the whole program. Node runs our code on a single
    // thread, so only one request touches the connection at a time. The Python
    // edition opens a new connection for every request because its server uses
    // several threads.
    const database = new DatabaseSync(DATABASE_FILE);

    // A prepared statement is SQL that the database has already read and checked.
    // We prepare each statement once, when the server starts, and run it many
    // times. If a table or column name were wrong, the error would appear here at
    // startup and not on the first click. The ? is a placeholder for a value that
    // travels separately from the SQL text, so a visitor can never change what the
    // SQL means (SQL injection).
    const selectAllSlots = database.prepare(
      "SELECT slot_id, item_name, price_cents, stock FROM inventory ORDER BY slot_id",
    );
    const selectOneSlot = database.prepare(
      "SELECT slot_id, item_name, price_cents, stock FROM inventory WHERE slot_id = ?",
    );
    // One statement checks the stock and changes it. If two buyers arrive at the
    // same moment, the database handles them one after the other, so they cannot
    // both take the last item.
    const decrementStockIfAvailable = database.prepare(
      "UPDATE inventory SET stock = stock - 1 WHERE slot_id = ? AND stock > 0",
    );

    // Run some work as a transaction: all of it happens, or none of it does.
    // The <T> means "whatever type the work returns", and the function returns the
    // same type.
    function runInTransaction   (work         )    {
      database.exec("BEGIN");
      try {
        const result = work();
        database.exec("COMMIT");
        return result;
      } catch (error) {
        // Something went wrong, so undo every change made since BEGIN.
        database.exec("ROLLBACK");
        throw error;
      }
    }

    function getAllSlots()         {
      // "as Slot[]" is a promise to the compiler. The compiler cannot see inside
      // the database, so it takes our word for the shape of the rows.
      return selectAllSlots.all()          ;
    }

    function getSlot(slotId        )       {
      const slot = selectOneSlot.get(slotId)                    ;
      if (slot === undefined) {
        throw new NoSuchSlot(`No slot called ${slotId}.`);
      }
      return slot;
    }

    // Take one item from a slot and return the updated slot.
    function buySlot(slotId        )       {
      return runInTransaction(() => {
        const updateResult = decrementStockIfAvailable.run(slotId);

        // Read the slot inside the same transaction, so that the numbers we report
        // agree with the change we just made. This line throws NoSuchSlot when the
        // slot does not exist.
        const slot = getSlot(slotId);

        // "changes" is the number of rows that the UPDATE changed.
        if (updateResult.changes === 0) {
          throw new SoldOut(`${slot.item_name} is sold out.`);
        }
        return slot;
      });
    }

    // --- Route layer -------------------------------------------------------------
    // A handler connects one URL to one data function. It checks the input, calls
    // the data layer and returns data. It contains no SQL and no HTTP details.

    // Tidy up a slot id from the URL and check that it has the right shape.
    function validateSlotId(rawSlotId        )         {
      // toUpperCase lets a visitor type a1 and mean A1.
      const slotId = rawSlotId.toUpperCase();
      if (!SLOT_ID_PATTERN.test(slotId)) {
        throw new BadRequest("Slot ids look like A1 or B2.");
      }
      return slotId;
    }

    function handleListSlots()         {
      return getAllSlots();
    }

    function handleShowSlot(rawSlotId        )       {
      return getSlot(validateSlotId(rawSlotId));
    }

    function handleBuySlot(rawSlotId        )       {
      return buySlot(validateSlotId(rawSlotId));
    }

    // One row of the route table: an HTTP method, a pattern for the URL path, and
    // the handler for that route.
              
                     
                      
                                                  
  

    // The route table is the API written as data. In a pattern, ([^/]+) captures
    // the text between two slashes, and the captured text is passed to the
    // handler as an argument.
    const ROUTES          = [
      { httpMethod: "GET", pathPattern: /^\/api\/slots$/, handler: handleListSlots },
      { httpMethod: "GET", pathPattern: /^\/api\/slots\/([^/]+)$/, handler: handleShowSlot },
      { httpMethod: "POST", pathPattern: /^\/api\/slots\/([^/]+)\/buy$/, handler: handleBuySlot },
    ];


    return { ROUTES, BadRequest, NoSuchSlot, SoldOut };
  })();

  const answer = createAnswerer(machine);
  globalThis.answerRequest = (httpMethod, urlPath) => answer(httpMethod, urlPath);
  postMessage({ type: "ready" });
}

onmessage = (event) => {
  const { id, method, path: requestPath } = event.data;
  const { status, body } = globalThis.answerRequest(method, requestPath.split("?")[0]);
  postMessage({ type: "reply", id, status, body });
};

start().catch((error) => postMessage({ type: "failed", message: String(error) }));
